import{_ as t,o as n,c as a,b6 as i}from"./chunks/framework.BUXTSoD9.js";const f=JSON.parse('{"title":"Projektvorstellung","description":"","frontmatter":{},"headers":[],"relativePath":"de-de/guide/introduction.md","filePath":"de-de/guide/introduction.md"}'),l={name:"de-de/guide/introduction.md"};function r(d,e,s,g,o,h){return n(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="projektvorstellung" tabindex="-1">Projektvorstellung <a class="header-anchor" href="#projektvorstellung" aria-label="Permalink to “Projektvorstellung”">​</a></h1><p>2025 wird von vielen als das erste Jahr der KI-Programmierung angesehen. Immer mehr Menschen beginnen, KI zum Schreiben von Code einzusetzen, aber die Ergebnisse bleiben oft auf Spielzeugebene -- man weiß nicht, wie man den Vibe Coding-Entwicklungsprozess organisiert, welche Tools man wählen soll und welche wichtigen Schritte vom Prototyp bis zum Go-Live noch fehlen.</p><p>Wir verwenden einen schrittweisen <strong>dreistufigen Praxis-Pfad</strong>: In der Anfängerphase steigen die Teilnehmer durch kleine Spiele schnell in die KI-Programmierung ein, in der ersten Phase erlernen sie die Vibe Coding-Arbeitsweise und erstellen Web-Anwendungsprototypen, in der zweiten Phase lernen sie die Full-Stack-Entwicklung und das Deployment, in der dritten Phase bauen sie komplexe, plattformübergreifende Anwendungen.</p><p>Jede Phase ist mit vollständigen Projektpraktika ausgestattet, damit Sie in echten Herausforderungen vom Spielzeug zum Produkt reifen und schließlich die Fähigkeit erwerben, <strong>jede Idee als nutzbare Anwendung zu realisieren</strong>.</p><p>Wir glauben, dass Sie mit der Beherrschung von Vibe Coding und systematischem Training ein <strong>Allround-Entwickler</strong> werden können, der Frontend- und Backend-Entwicklung, KI-Fähigkeitsintegration und Produktdesign in sich vereint.</p><p>Dieses Projekt richtet sich hauptsächlich an drei Arten von Lernenden:</p><ul><li><strong>Anfänger (Allrounder / Produkt- und Betriebsseite)</strong>: Hilft Nicht-Technik-Background-Rollen und Einsteigern, Schlüsselkonzepte zu verstehen und das erste KI-Kleintool oder den ersten Produktprototyp abzuschließen.</li><li><strong>Mittelstufe-Entwickler (Studierende und Entwickler mit gewissen Grundlagen)</strong>: Systematische Beherrschung von Vibe Coding und nativer KI-Anwendungsentwicklung.</li><li><strong>Fortgeschrittene Entwickler (Unternehmen &amp; Startups, Open-Source- und Indie-Entwickler)</strong>: Unterstützt Teams und Einzelpersonen beim schnellen Aufbau, der Validierung und Iteration nativer KI-Anwendungen.</li></ul><h2 id="inhaltliche-navigation" tabindex="-1">Inhaltliche Navigation <a class="header-anchor" href="#inhaltliche-navigation" aria-label="Permalink to “Inhaltliche Navigation”">​</a></h2><h3 id="gesamtanhang" tabindex="-1">Gesamtanhang <a class="header-anchor" href="#gesamtanhang" aria-label="Permalink to “Gesamtanhang”">​</a></h3><p><a href="/easy-vibe-ja-learning-map/de-de/appendix/8-artificial-intelligence/ai-capability-dictionary.html">KI-Fähigkeitswörterbuch: Gängige KI-Kernkonzepte, Begriffe und Szenario-Erklärungen</a></p><h3 id="null-kindergarten" tabindex="-1">Null, Kindergarten <a class="header-anchor" href="#null-kindergarten" aria-label="Permalink to “Null, Kindergarten”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Kapitel</th><th style="text-align:left;">Wichtige Inhalte</th><th style="text-align:left;">Status</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/de-de/stage-1/learning-map/">Anfänger: Lernkarte</a></td><td style="text-align:left;">Gesamtübersicht des Lernpfads</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/de-de/stage-1/ai-capabilities-through-games/">Anfänger: Im KI-Zeitalter genügt Sprechen zum Programmieren</a></td><td style="text-align:left;">Erste Erfahrungen mit KI-Programmierung am Beispiel von Snake</td><td style="text-align:left;">✅</td></tr></tbody></table><h3 id="eins-ki-produktmanager" tabindex="-1">Eins, KI-Produktmanager <a class="header-anchor" href="#eins-ki-produktmanager" aria-label="Permalink to “Eins, KI-Produktmanager”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Kapitel</th><th style="text-align:left;">Wichtige Inhalte</th><th style="text-align:left;">Status</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/de-de/stage-1/introduction-to-ai-ide/">Anfänger II: KI-IDE-Tools kennenlernen</a></td><td style="text-align:left;">IDE bedienen, Benutzeroberfläche und effiziente Prompt-Methoden beherrschen</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/de-de/stage-1/building-prototype/">Anfänger III: Prototypen erstellen</a></td><td style="text-align:left;">Vom Produkt-Analysis bis zum Multi-Page-Produktprototyp -- vollständiger Zyklus</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/de-de/stage-1/integrating-ai-capabilities/">Anfänger IV: KI-Fähigkeiten in den Prototyp einbauen</a></td><td style="text-align:left;">API-Integration gängiger KI-Fähigkeiten (Text, Bild, Video) verstehen und umsetzen</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/de-de/stage-1/complete-project-practice/">Anfänger V: Vollständiges Projektpraktikum</a></td><td style="text-align:left;">Echte Szenarien simulieren, Nutzerfeedback iterativ einarbeiten und Projekt präsentieren (inkl. Abschlussaufgabe)</td><td style="text-align:left;">✅</td></tr></tbody></table><h4 id="anhang" tabindex="-1">Anhang <a class="header-anchor" href="#anhang" aria-label="Permalink to “Anhang”">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">Kapitel</th><th style="text-align:left;">Wichtige Inhalte</th><th style="text-align:left;">Status</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/de-de/stage-1/appendix-a-product-thinking/">Anhang A: Produkt-Denken Ergänzung</a></td><td style="text-align:left;">Produkt-Denken-Rahmen von der Ideenbewertung bis zur Anforderungsaufschlüsselung und MVP</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/de-de/stage-1/appendix-b-common-errors/">Anhang B: Häufige Fehler und Lösungen</a></td><td style="text-align:left;">Häufige Fehler und Behebungsstrategien beim Vibe Coding</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/de-de/stage-1/appendix-idea-sources/">Anhang: Woher Ideen finden</a></td><td style="text-align:left;">Nischige Richtungen aus Referenz-Apps, Trends und VC-Listen ableiten</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/de-de/stage-1/appendix-double-diamond/">Anhang: Double-Diamond-Modell</a></td><td style="text-align:left;">Verstehen, zuerst das Problem zu definieren, bevor man die Lösung entwirft</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/de-de/stage-1/appendix-jobs-to-be-done/">Anhang: Jobs to Be Done</a></td><td style="text-align:left;">Mit der JTBD-Methode erkennen, was Nutzer wirklich erreichen wollen</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/de-de/stage-1/appendix-mom-test/">Anhang: The Mom Test Interview-Methode</a></td><td style="text-align:left;">Bedarfsvalidierung durch Nutzerinterviews</td><td style="text-align:left;">✅</td></tr></tbody></table><h3 id="zwei-junior-mid-level-entwickler" tabindex="-1">Zwei, Junior-/Mid-Level-Entwickler <a class="header-anchor" href="#zwei-junior-mid-level-entwickler" aria-label="Permalink to “Zwei, Junior-/Mid-Level-Entwickler”">​</a></h3><h4 id="frontend-bereich" tabindex="-1">Frontend-Bereich <a class="header-anchor" href="#frontend-bereich" aria-label="Permalink to “Frontend-Bereich”">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">Kapitel</th><th style="text-align:left;">Wichtige Inhalte</th><th style="text-align:left;">Status</th></tr></thead><tbody><tr><td style="text-align:left;">Lovart zur Materialerstellung nutzen</td><td style="text-align:left;">Lovart zum Batch-Generieren von visuellen Materialien wie Charakteren und Szenen beherrschen, Materialgrundlage für UI-Design und Frontend-Entwicklung schaffen</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Figma und MasterGo Einführung</td><td style="text-align:left;">Design-Tools zur Informationsarchitektur und Seitenstruktur nutzen, Grundlage für die Frontend-Implementierung schaffen</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Erste moderne Anwendung erstellen -- UI-Design</td><td style="text-align:left;">Komponentenbasierte Oberfläche basierend auf Designentwürfen umsetzen, erste Pipeline vom Design zum Code</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Seiten und Schaltflächen nach UI-Design-Richtlinien gestalten</td><td style="text-align:left;">Mainstream-Design-Richtlinien für Seitenstruktur und Schaltflächen-Hierarchie lernen und KI-gestützte Designentwürfe erstellen</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/de-de/stage-2/frontend/hogwarts-portraits/">Hogwarts-Portraits gemeinsam erstellen</a></td><td style="text-align:left;">Eine Frontend-Anwendung mit KI-Fähigkeiten von 0 auf 1 erstellen, Design und Entwicklung verknüpfen</td><td style="text-align:left;">🚧</td></tr></tbody></table><h4 id="backend-entwicklung" tabindex="-1">Backend-Entwicklung <a class="header-anchor" href="#backend-entwicklung" aria-label="Permalink to “Backend-Entwicklung”">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">Kapitel</th><th style="text-align:left;">Wichtige Inhalte</th><th style="text-align:left;">Status</th></tr></thead><tbody><tr><td style="text-align:left;">Was ist eine API?</td><td style="text-align:left;">HTTP-Schnittstellen und Request-Response-Modell verstehen, Vorbereitung auf Backend-Integration und Abstimmung</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/de-de/stage-2/backend/database-supabase/">Von der Datenbank zu Supabase</a></td><td style="text-align:left;">Datenbank und API auf Supabase umsetzen, Datenmodell und Frontend-Seite verknüpfen</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">LLM-unterstütztes Schreiben von API-Code und API-Dokumentation</td><td style="text-align:left;">LLM beim Generieren von API- und Datenbankdokumentation sowie Code unterstützen, lesbaren und testbaren Backend-Code erstellen</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Git-Workflow und Zeabur-Deployment</td><td style="text-align:left;">Code im Git-Workflow verwalten und die Anwendung auf Zeabur bereitstellen</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Moderne CLI-Entwicklungstools</td><td style="text-align:left;">CLI-basierte KI-Programmierungstools zur Beschleunigung von Entwicklung und Debugging nutzen, einen persönlichen Engineering-Workflow aufbauen</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Stripe-Integration und andere Zahlungssysteme</td><td style="text-align:left;">Zahlungssystem integrieren, Zahlungs-Pipeline und grundlegende Abrechnungsprozesse abschließen</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Erste moderne Anwendung erstellen -- Full-Stack-Anwendung</td><td style="text-align:left;">Frontend, Backend und Zahlungsmodul integrieren, eine bereitstellbare Full-Stack-Web-Anwendung erstellen</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Moderne Frontend-Komponentenbibliothek + Trae-Praxis</td><td style="text-align:left;">Moderne Frontend-Komponentenbibliothek und Trae nutzen, unabhängig ein Produkt mit Login/Registrierung und Zahlungsunterstützung erstellen</td><td style="text-align:left;">🚧</td></tr></tbody></table><h4 id="ki-f-auml-higkeiten-anhang" tabindex="-1">KI-Fähigkeiten Anhang <a class="header-anchor" href="#ki-f-auml-higkeiten-anhang" aria-label="Permalink to “KI-F&amp;auml;higkeiten Anhang”">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">Kapitel</th><th style="text-align:left;">Wichtige Inhalte</th><th style="text-align:left;">Status</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/de-de/stage-2/ai-capabilities/dify-knowledge-base/">Dify-Einführung und Wissensdatenbank-Integration</a></td><td style="text-align:left;">Dify Workflow und grundlegendes RAG zum Aufbau eines toolbasierten Produkts nutzen, Vorlage für spätere App-Upgrades erstellen</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">KI-Wörterbuch abfragen und multimodale APIs integrieren</td><td style="text-align:left;">Geeignete Modelle und APIs finden und multimodale Fähigkeiten wie Text und Bild in Produkte integrieren</td><td style="text-align:left;">🚧</td></tr></tbody></table><h3 id="drei-senior-entwickler" tabindex="-1">Drei, Senior-Entwickler <a class="header-anchor" href="#drei-senior-entwickler" aria-label="Permalink to “Drei, Senior-Entwickler”">​</a></h3>',24)])])}const c=t(l,[["render",r]]);export{f as __pageData,c as default};
